            attr_slug_provided_as_none = attr_slug is None and "slug" in attr
            if attr_slug_provided_as_none:
                value_as_empty_or_null_list.append(str(index))
                continue

            value_as_empty = "value" in attr and not attr["value"]
            if value_as_empty:
                value_as_empty_or_null_list.append(str(index))
